layer.css:
[data-ryt="pitch"] { color: rgb(176, 180, 190); background-color: rgba(24, 24, 29, 0.922); border-radius: 12px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(176, 180, 190); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 16px; padding-right: 20px; padding-bottom: 16px; padding-left: 20px; transition: all }
[data-ryt="footer"] { color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="hero"] h1 { color: rgb(176, 180, 190); font-family: var(--ryt-font-heading); font-size: 56px; font-weight: 700; font-style: normal; line-height: 1.08; letter-spacing: -1.184px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(176, 180, 190); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="section"] > h2 { color: rgb(176, 180, 190); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; line-height: 1.08; letter-spacing: -1.184px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(176, 180, 190); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 700; font-style: normal; line-height: 1.8; letter-spacing: 1.28px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-header-text); border-radius: 999px; font-family: var(--ryt-font-heading); font-size: 15.2px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-header-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7.2px; padding-right: 11.2px; padding-bottom: 7.2px; padding-left: 11.2px; transition: background-color 0.2s ease-out, color 0.2s ease-out }
[data-ryt="review"] { color: var(--ryt-text); font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: var(--ryt-muted); font-family: var(--ryt-font-heading); font-size: 15.04px; font-weight: 400; font-style: normal; line-height: 1.8; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-muted); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: rgb(142, 187, 209); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 700; font-style: normal; letter-spacing: -0.688px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(142, 187, 209); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
body { background-image: radial-gradient(circle at 50% 0%, rgba(0, 118, 206, 0.102), rgba(0, 0, 0, 0) 28%), none; background-size: auto, auto; background-position: 0% 0%, 0% 0%; background-repeat: repeat, repeat }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(176, 180, 190); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 34px; font-weight: 700; font-style: normal; line-height: 1.08; letter-spacing: -0.688px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(176, 180, 190); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #79c0dc; color: #79c0dc }
[data-ryt="nav"] a:hover { color: #79c0dc; color: #79c0dc }
[data-ryt="brand"]:hover { color: #79c0dc }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #79c0dc; color: #79c0dc }
